enum Direction {
    North,
    East,
    South,
    West,
}

impl Direction {
    fn turn_right(self) -> Direction {
        match self {
            Direction::North => Direction::East,
            Direction::East => Direction::South,
            Direction::South => Direction::West,
            Direction::West => Direction::North,
        }
    }
}

fn main() {
    let d = Direction::North;
    let d = d.turn_right();
    let d = d.turn_right();
    match d {
        Direction::South => println!("facing south"),
        _ => println!("facing another way"),
    }
}

enum Shape {
    Square(f64),
    Rect(f64, f64),
    Triangle(f64, f64),
}

impl Shape {
    fn area(&self) -> f64 {
        match self {
            Shape::Square(s) => s * s,
            Shape::Rect(w, h) => w * h,
            Shape::Triangle(b, h) => b * h / 2.0,
        }
    }
}

fn main() {
    println!("{}", Shape::Square(3.0).area());
    println!("{}", Shape::Rect(2.0, 6.0).area());
    println!("{}", Shape::Triangle(4.0, 5.0).area());
}

